33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/** Rounds to whole G in the MHPCO's favour. */
68	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
69	
70	const quotePremium = (items: Item[]): number => {
71	  const policyBasePremium = items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
72	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
73	  return roundUpToWholeG(policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE);
74	};
75	
76	export const runScenario = (scenario: Scenario): ScenarioResult => {
77	  return {
78	    results: scenario.steps.map((step) => ({
79	      premium: quotePremium((step as QuoteStep).items),
80	    })),
81	  };
82	};
